<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller; use App\Models\EcosystemSectorPack; use App\Models\EcosystemSectorPackVersion; use Composer\Semver\Semver; use Illuminate\Database\Query\Builder; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; use Symfony\Component\HttpFoundation\Response;
class EcosystemSectorPackController extends Controller {
 private function view(Request $r):void{abort_unless($r->user()->hasPermission('ecosystem.modules.view'),403);} private function write(Request $r):void{abort_unless($r->user()->hasPermission('ecosystem.modules.configure'),403);}
 public function dashboard(Request $r):JsonResponse{$this->view($r);$packs=DB::table('ecosystem_sector_packs')->whereNull('deleted_at');$versions=DB::table('ecosystem_sector_pack_versions');$modules=DB::table('ecosystem_sector_pack_modules');$bundles=DB::table('ecosystem_capability_bundles');$tenants=DB::table('ecosystem_sector_pack_tenants');$exceptions=DB::table('ecosystem_sector_pack_exceptions')->where('status','open');$count=fn($s)=>(clone $packs)->where('status',$s)->count();return $this->successResponse(['dashboard'=>['summary'=>['packs'=>(clone $packs)->count(),'active'=>$count('active'),'review'=>$count('in_review'),'draft'=>$count('draft'),'deprecated'=>$count('deprecated'),'versions'=>(clone $versions)->count(),'modules'=>(clone $modules)->count(),'bundles'=>(clone $bundles)->count(),'tenants'=>(clone $tenants)->distinct('company_profile_id')->count('company_profile_id'),'exceptions'=>(clone $exceptions)->count()],'release'=>$this->releaseSummary(),'health'=>['score'=>null,'status'=>(clone $packs)->count()?'not_evaluated':'not_evaluated','reason'=>'No documented numeric sector-pack health model exists.'],'statuses'=>$this->distribution($packs,'status'),'risks'=>$this->distribution($packs,'risk_level'),'exceptions'=>$this->distribution($exceptions,'severity'),'activity'=>$this->activity(),'permissions'=>['canCreate'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canVersion'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canRelease'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canExport'=>$r->user()->hasPermission('ecosystem.modules.view')],'generatedAt'=>now()->toIso8601String(),'source'=>'database']]);}
 public function index(Request $r):JsonResponse{$this->view($r);$v=$r->validate(['search'=>['nullable','string','max:160'],'status'=>['nullable','string','max:30'],'industry'=>['nullable','string','max:100'],'risk'=>['nullable','string','max:20'],'sort'=>['nullable',Rule::in(['name','code','status','industry','risk_level','updated_at'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer','min:1','max:100']]);$q=$this->registry();if($s=trim((string)($v['search']??'')))$q->where(fn($x)=>$x->where('p.name','like',"%$s%")->orWhere('p.code','like',"%$s%")->orWhere('p.industry','like',"%$s%"));foreach(['status'=>'p.status','industry'=>'p.industry','risk'=>'p.risk_level'] as $k=>$c)if(!empty($v[$k]))$q->where($c,$v[$k]);$sort='p.'.($v['sort']??'updated_at');$page=$q->orderBy($sort,$v['direction']??'desc')->paginate($v['per_page']??20);return $this->successResponse(['packs'=>$page]);}
 public function show(Request $r,string $slug):JsonResponse{$this->view($r);$pack=DB::table('ecosystem_sector_packs as p')->leftJoin('ecosystem_sector_pack_versions as v','v.id','=','p.current_version_id')->whereNull('p.deleted_at')->where('p.slug',$slug)->first(['p.*','v.id as version_id','v.version','v.status as version_status','v.release_channel','v.target_release_at','v.released_at','v.released_by','v.lock_version']);abort_unless($pack,404,'Sector pack not found.');$versionId=$pack->version_id;$modules=$versionId?DB::table('ecosystem_sector_pack_modules as pm')->join('ecosystem_modules as m','m.id','=','pm.ecosystem_module_id')->where('pm.sector_pack_version_id',$versionId)->get(['pm.id','m.id as module_id','m.module_key','m.name','m.category','m.current_version','pm.requirement','pm.minimum_version','pm.maximum_version','pm.compatibility_status','pm.validation_reasons']):collect();$bundles=$versionId?DB::table('ecosystem_sector_pack_bundles as pb')->join('ecosystem_capability_bundles as b','b.id','=','pb.capability_bundle_id')->where('pb.sector_pack_version_id',$versionId)->select('b.id','b.bundle_key','b.name','b.status','pb.requirement')->selectSub(fn($q)=>$q->from('ecosystem_capability_bundle_items')->whereColumn('capability_bundle_id','b.id')->selectRaw('COUNT(*)'),'capability_count')->get():collect();$countries=$versionId?DB::table('ecosystem_sector_pack_countries as pc')->join('countries as c','c.id','=','pc.country_id')->where('pc.sector_pack_version_id',$versionId)->get(['c.id','c.name','c.iso2 as code','pc.status','pc.reason','pc.approval_required']):collect();$tenantUsage=DB::table('ecosystem_sector_pack_tenants')->where('sector_pack_id',$pack->id)->selectRaw('status, COUNT(*) as count')->groupBy('status')->get();$exceptions=DB::table('ecosystem_sector_pack_exceptions')->where('sector_pack_id',$pack->id)->where('status','open')->orderByDesc('created_at')->get();$versions=DB::table('ecosystem_sector_pack_versions')->where('sector_pack_id',$pack->id)->orderByDesc('id')->get();return $this->successResponse(['pack'=>['metadata'=>$pack,'summary'=>['modules'=>$modules->count(),'requiredModules'=>$modules->where('requirement','required')->count(),'optionalModules'=>$modules->where('requirement','optional')->count(),'bundles'=>$bundles->count(),'countries'=>$countries->count(),'tenants'=>$tenantUsage->sum('count'),'exceptions'=>$exceptions->count()],'modules'=>$modules,'bundles'=>$bundles,'countries'=>$countries,'tenantUsage'=>$tenantUsage,'exceptions'=>$exceptions,'versions'=>$versions,'compatibility'=>$this->compatibility($modules),'releaseReadiness'=>$this->readiness($modules,$exceptions),'activity'=>$this->activity($pack->id),'permissions'=>['canEdit'=>$r->user()->hasPermission('ecosystem.modules.configure')&&$pack->version_status==='draft','canVersion'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canRelease'=>$r->user()->hasPermission('ecosystem.modules.configure')&&$pack->version_status==='draft','canExport'=>$r->user()->hasPermission('ecosystem.modules.view')]]]);}
 public function store(Request $r):JsonResponse{$this->write($r);$d=$r->validate(['name'=>['required','string','max:160'],'slug'=>['required','alpha_dash','max:160','unique:ecosystem_sector_packs,slug'],'code'=>['required','string','max:60','unique:ecosystem_sector_packs,code'],'description'=>['nullable','string'],'sector'=>['nullable','string','max:100'],'industry'=>['nullable','string','max:100'],'owner'=>['nullable','string','max:160'],'version'=>['required','string','max:40']]);$this->assertVersion($d['version']);$pack=DB::transaction(function()use($r,$d){$pack=EcosystemSectorPack::create([...$d,'uuid'=>(string)Str::uuid(),'status'=>'draft','risk_level'=>'unknown','created_by'=>$r->user()->id,'updated_by'=>$r->user()->id]);$version=EcosystemSectorPackVersion::create(['uuid'=>(string)Str::uuid(),'sector_pack_id'=>$pack->id,'version'=>$d['version'],'status'=>'draft']);$pack->update(['current_version_id'=>$version->id]);$this->audit($pack->id,$version->id,$r,'created',null,$pack->toArray());return $pack;});return $this->successResponse(['pack'=>$pack],'Sector pack created.',Response::HTTP_CREATED);}
 public function update(Request $r,string $slug):JsonResponse{$this->write($r);$pack=EcosystemSectorPack::where('slug',$slug)->firstOrFail();$version=EcosystemSectorPackVersion::findOrFail($pack->current_version_id);abort_if($version->status!=='draft',409,'Released and non-draft versions are immutable. Create a new version.');$d=$r->validate(['name'=>['sometimes','string','max:160'],'description'=>['sometimes','nullable','string'],'sector'=>['sometimes','nullable','string','max:100'],'industry'=>['sometimes','nullable','string','max:100'],'owner'=>['sometimes','nullable','string','max:160'],'risk_level'=>['sometimes',Rule::in(['unknown','low','medium','high','critical'])],'lock_version'=>['required','integer']]);abort_if((int)$d['lock_version']!==$version->lock_version,409,'This version was changed by another administrator.');DB::transaction(function()use($r,$pack,$version,$d){$before=$pack->toArray();unset($d['lock_version']);$pack->update([...$d,'updated_by'=>$r->user()->id]);$version->increment('lock_version');$this->audit($pack->id,$version->id,$r,'updated',$before,$pack->fresh()->toArray());});return $this->successResponse(['pack'=>$pack->fresh()],'Draft updated.');}
 public function newVersion(Request $r,string $slug):JsonResponse{$this->write($r);$d=$r->validate(['version'=>['required','string','max:40']]);$this->assertVersion($d['version']);$pack=EcosystemSectorPack::where('slug',$slug)->firstOrFail();$new=DB::transaction(function()use($r,$pack,$d){$locked=EcosystemSectorPack::whereKey($pack->id)->lockForUpdate()->first();abort_if(EcosystemSectorPackVersion::where('sector_pack_id',$pack->id)->where('version',$d['version'])->exists(),409,'Version already exists.');$old=EcosystemSectorPackVersion::find($locked->current_version_id);$new=EcosystemSectorPackVersion::create(['uuid'=>(string)Str::uuid(),'sector_pack_id'=>$pack->id,'version'=>$d['version'],'status'=>'draft']);if($old){DB::table('ecosystem_sector_pack_modules')->where('sector_pack_version_id',$old->id)->get()->each(function($row)use($new){$x=(array)$row;unset($x['id']);$x['sector_pack_version_id']=$new->id;$x['created_at']=$x['updated_at']=now();DB::table('ecosystem_sector_pack_modules')->insert($x);});DB::table('ecosystem_sector_pack_bundles')->where('sector_pack_version_id',$old->id)->get()->each(function($row)use($new){$x=(array)$row;unset($x['id']);$x['sector_pack_version_id']=$new->id;$x['created_at']=$x['updated_at']=now();DB::table('ecosystem_sector_pack_bundles')->insert($x);});DB::table('ecosystem_sector_pack_countries')->where('sector_pack_version_id',$old->id)->get()->each(function($row)use($new){$x=(array)$row;unset($x['id']);$x['sector_pack_version_id']=$new->id;$x['created_at']=$x['updated_at']=now();DB::table('ecosystem_sector_pack_countries')->insert($x);});}$locked->update(['current_version_id'=>$new->id,'status'=>'draft','updated_by'=>$r->user()->id]);$this->audit($pack->id,$new->id,$r,'version_created',null,$new->toArray());return $new;});return $this->successResponse(['version'=>$new],'Draft version created.',Response::HTTP_CREATED);}
 public function release(Request $r,string $slug):JsonResponse{$this->write($r);$pack=EcosystemSectorPack::where('slug',$slug)->firstOrFail();$released=DB::transaction(function()use($r,$pack){$locked=EcosystemSectorPackVersion::whereKey($pack->current_version_id)->lockForUpdate()->firstOrFail();abort_if($locked->status!=='draft',409,'Only a draft version can be released.');$invalid=DB::table('ecosystem_sector_pack_modules')->where('sector_pack_version_id',$locked->id)->whereNotIn('compatibility_status',['compatible'])->count();abort_if($invalid>0,422,'All module compatibility checks must pass before release.');$locked->update(['status'=>'released','released_at'=>now(),'released_by'=>$r->user()->id]);$pack->update(['status'=>'active','updated_by'=>$r->user()->id]);$this->audit($pack->id,$locked->id,$r,'released',null,$locked->fresh()->toArray());return $locked->fresh();});return $this->successResponse(['version'=>$released],'Version released.');}
 public function export(Request $r,?string $slug=null){$this->view($r);$data=$slug?$this->definition($slug):$this->registry()->orderBy('p.name')->get();return response()->json(['exportedAt'=>now()->toIso8601String(),'source'=>'database','data'=>$data]);}
 private function registry():Builder{return DB::table('ecosystem_sector_packs as p')->leftJoin('ecosystem_sector_pack_versions as v','v.id','=','p.current_version_id')->whereNull('p.deleted_at')->select('p.id','p.uuid','p.slug','p.code','p.name','p.sector','p.industry','p.status','p.risk_level','p.owner','p.updated_at','v.id as version_id','v.version','v.status as version_status','v.target_release_at','v.released_at')->selectSub(fn($q)=>$q->from('ecosystem_sector_pack_modules')->whereColumn('sector_pack_version_id','v.id')->selectRaw('COUNT(*)'),'module_count')->selectSub(fn($q)=>$q->from('ecosystem_sector_pack_bundles')->whereColumn('sector_pack_version_id','v.id')->selectRaw('COUNT(*)'),'bundle_count')->selectSub(fn($q)=>$q->from('ecosystem_sector_pack_tenants')->whereColumn('sector_pack_id','p.id')->selectRaw('COUNT(*)'),'tenant_count')->selectSub(fn($q)=>$q->from('ecosystem_sector_pack_exceptions')->whereColumn('sector_pack_id','p.id')->where('status','open')->selectRaw('COUNT(*)'),'exception_count');}
 private function definition(string $slug){$pack=DB::table('ecosystem_sector_packs')->where('slug',$slug)->whereNull('deleted_at')->first();abort_unless($pack,404);return['pack'=>$pack,'versions'=>DB::table('ecosystem_sector_pack_versions')->where('sector_pack_id',$pack->id)->get(),'modules'=>DB::table('ecosystem_sector_pack_modules')->whereIn('sector_pack_version_id',DB::table('ecosystem_sector_pack_versions')->where('sector_pack_id',$pack->id)->pluck('id'))->get()];}
 private function compatibility($modules):array{$counts=['compatible'=>0,'partial'=>0,'incompatible'=>0,'not_evaluated'=>0];foreach($modules as $m)$counts[array_key_exists($m->compatibility_status,$counts)?$m->compatibility_status:'not_evaluated']++;return['counts'=>$counts,'status'=>$modules->isEmpty()?'not_evaluated':($counts['incompatible']?'incompatible':($counts['not_evaluated']?'not_evaluated':'compatible'))];}
 private function readiness($modules,$exceptions):array{$failed=$modules->where('compatibility_status','incompatible')->count()+$exceptions->whereIn('severity',['critical','high'])->count();$pending=$modules->where('compatibility_status','not_evaluated')->count();return['ready'=>$failed===0&&$pending===0&&!$modules->isEmpty(),'status'=>$failed?'blocked':($pending||$modules->isEmpty()?'not_evaluated':'ready'),'failed'=>$failed,'pending'=>$pending,'passed'=>$modules->where('compatibility_status','compatible')->count(),'reasons'=>[]];}
 private function releaseSummary(){return DB::table('ecosystem_sector_pack_versions as v')->join('ecosystem_sector_packs as p','p.id','=','v.sector_pack_id')->where('v.status','released')->orderByDesc('v.released_at')->first(['p.slug','p.name','v.version','v.released_at','v.released_by']);}
 private function distribution(Builder $q,string $column){return (clone $q)->select($column.' as key',DB::raw('COUNT(*) as count'))->groupBy($column)->get();}
 private function activity(?int $id=null){$q=DB::table('ecosystem_sector_pack_audits as a')->leftJoin('users as u','u.id','=','a.actor_id');if($id)$q->where('a.sector_pack_id',$id);return $q->orderByDesc('a.created_at')->limit(12)->get(['a.id','a.sector_pack_id','a.version_id','a.action','u.name as actor','a.created_at']);}
 private function audit(int $pack,?int $version,Request $r,string $action,?array $before,?array $after):void{DB::table('ecosystem_sector_pack_audits')->insert(['sector_pack_id'=>$pack,'version_id'=>$version,'action'=>$action,'actor_id'=>$r->user()->id,'before'=>$before?json_encode($before):null,'after'=>$after?json_encode($after):null,'created_at'=>now()]);}
 private function assertVersion(string $version):void{if(!preg_match('/^v?\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/',$version))throw ValidationException::withMessages(['version'=>'Version must use semantic version syntax.']);}
}
